    { tooltip_id = "ability:ability_survival_chain_lightning", tooltip_type = "ability", id = "ability_survival_chain_lightning", name = "怒雷·被动", needwood = "0", needgold = "0", desc = "等级1：普通攻击命中时，20%概率对目标落雷，造成全属性总和×3伤害，并对400范围内其他敌人造成50%伤害。 等级2：怒雷命中目标施加3秒标记；标记期间再次被怒雷命中，额外受到全属性总和×1.5伤害。每次命中都会刷新标记。 等级3：触发概率提高至45%；被标记的敌人攻击力降低15%，持续至标记结束。 等级4：完整继承等级3效果，无额外变化。 等级5：怒雷连续释放3道；同一目标重复被落雷命中时，该目标从第二道起每道伤害减半。每道雷都会触发标记效果。", icon = "zuus_lightning_bolt", source_id = "proto_chain_lightning" },
    { tooltip_id = "ability:ability_survival_doom_infernal", tooltip_type = "ability", id = "ability_survival_doom_infernal", name = "末日使者专属：地狱火", needwood = "0", needgold = "0", desc = "一转后激活。普通攻击命中时有10%概率召唤术士地狱火，继承触发时英雄100%攻击力、攻击速度、最大生命与防御，持续10秒。地狱火不继承英雄或装备攻击附带效果；存续期间跳过召唤概率判定。", icon = "warlock_rain_of_chaos", source_id = "skill_doom_infernal" },
