    { tooltip_id = "ability:ability_survival_monkey_king_swiftness", tooltip_type = "ability", id = "ability_survival_monkey_king_swiftness", name = "齐天大圣专属：齐天", needwood = "0", needgold = "0", desc = "六转激活。最终攻击力使用独立三倍乘区；仅本体主普通攻击实际暴击时对主目标追加全属性×5纯粹伤害。", icon = "monkey_king_tree_dance", source_id = "skill_monkey_king_swiftness" },
    { tooltip_id = "ability:ability_survival_poison_cloud", tooltip_type = "ability", id = "ability_survival_poison_cloud", name = "毒云·被动", needwood = "0", needgold = "0", desc = "等级1：普通攻击命中时，12%概率在目标位置生成400范围毒云，持续5秒；第1至第5秒各造成一次触发时全属性总和×1纯粹伤害。毒云活动期间同一英雄不会再次触发毒云。 等级2：毒云每次整秒伤害命中使敌人的实时总护甲降低20%，最多3层（60%）；离开毒云或毒云消失时立即恢复毒云降低的护甲。 等级3：触发概率提高至20%，毒云持续时间增加至7秒，因此第1至第7秒各造成一次伤害。 等级4：完整继承等级3效果，无额外变化。 等级5：毒云中的敌人死亡时，以死亡位置为中心对300范围造成一次触发时全属性总和×3纯粹伤害；死亡爆炸可继续引发毒云内敌人的连锁爆炸。", icon = "viper_nethertoxin", source_id = "proto_poison_cloud" },
    { tooltip_id = "ability:ability_survival_shadow_fiend_raze", tooltip_type = "ability", id = "ability_survival_shadow_fiend_raze", name = "影魔专属：影压", needwood = "0", needgold = "0", desc = "一转后激活。普通攻击命中时有10%概率在目标位置释放250范围影压。影压先增加1层再造成纯粹伤害，1至5层分别为全属性×27.5、×30、×32.5、×35、×37.5；最多5层，每层独立持续3秒。", icon = "nevermore_shadowraze1", source_id = "skill_shadow_fiend_raze" },
    { tooltip_id = "ability:ability_survival_void_pulse", tooltip_type = "ability", id = "ability_survival_void_pulse", name = "虚空震爆·被动", needwood = "0", needgold = "0", desc = "等级1：普通攻击命中时有15%概率从攻击者位置释放龙卷风。龙卷风以500速度追踪原攻击目标，第一次到达后附着跟随目标；目标死亡则停在死亡位置。持续3秒，在生成时及第1、2秒实时读取全属性，对中心300范围造成全属性×2纯粹伤害。 等级2：完整继承等级1效果，无额外变化。 等级3：龙卷风中心600范围内的敌人持续降低20%移动速度；被主龙卷伤害命中的敌人在仍处于该范围时额外降低15%，总计35%，离开范围立即移除。 等级4：完整继承等级3效果，无额外变化。 等级5：主龙卷结束时，按仍存活的已命中不同目标数量在结束位置生成小龙卷。小龙卷随机选择这些目标的方向，以相同速度移动2秒，每秒造成主龙卷60%的实时属性伤害，并仅施加20%范围减速。", icon = "invoker_tornado", source_id = "proto_void_pulse" },
